import ast
from pathlib import Path

import pytest

from lake.layers.decode import decode_brand, decode_channels, read_varint

DECODE_SOURCE = Path(__file__).resolve().parents[1] / "dags" / "lake" / "layers" / "decode.py"

# Byte fixtures are written out by hand, not generated by the code under test.
VARINT_FIXTURES = [
    (b"\x00", 0),
    (b"\x01", 1),
    (b"\x7f", 127),
    (b"\x80\x01", 128),
    (b"\xff\x01", 255),
    (b"\xac\x02", 300),
    (b"\xff\x7f", 16383),
    (b"\x80\x80\x01", 16384),
    (b"\xff\xff\xff\xff\x07", 2147483647),
]


@pytest.mark.parametrize(("data", "value"), VARINT_FIXTURES)
def test_read_varint_decodes_fixture(data, value):
    assert read_varint(data) == (value, len(data))


def test_read_varint_starts_at_offset_and_returns_next_offset():
    data = b"\xff\xac\x02\x05"

    assert read_varint(data, offset=1) == (300, 3)


def test_read_varint_rejects_truncated_value():
    with pytest.raises(ValueError, match="truncated"):
        read_varint(b"\x80")


def test_read_varint_rejects_empty_input():
    with pytest.raises(ValueError, match="truncated"):
        read_varint(b"")


def test_read_varint_rejects_more_than_five_bytes():
    with pytest.raises(ValueError, match="too long"):
        read_varint(b"\x80\x80\x80\x80\x80\x01")


def test_read_varint_rejects_value_above_signed_32_bit():
    with pytest.raises(ValueError, match="32-bit"):
        read_varint(b"\xff\xff\xff\xff\x0f")


def test_decode_brand_reads_single_byte_length_prefix():
    assert decode_brand(b"\x06fabric") == "fabric"


def test_decode_brand_reads_multi_byte_length_prefix():
    payload = b"\x80\x01" + b"x" * 128

    assert decode_brand(payload) == "x" * 128


def test_decode_brand_counts_length_in_utf8_bytes():
    # "brand" is 5 bytes and the umlaut is 2 bytes, so the prefix is 7.
    assert decode_brand(b"\x07brand\xc3\xbc") == "brandü"


def test_decode_brand_accepts_empty_brand():
    assert decode_brand(b"\x00") == ""


def test_decode_brand_rejects_truncated_brand():
    with pytest.raises(ValueError, match="truncated"):
        decode_brand(b"\x06fab")


def test_decode_brand_rejects_trailing_bytes():
    with pytest.raises(ValueError, match="trailing"):
        decode_brand(b"\x03fab\x00")


def test_decode_brand_rejects_invalid_utf8():
    with pytest.raises(ValueError, match="UTF-8"):
        decode_brand(b"\x02\xff\xfe")


def test_decode_brand_rejects_empty_payload():
    with pytest.raises(ValueError, match="truncated"):
        decode_brand(b"")


def test_decode_channels_splits_on_nul():
    payload = b"minecraft:brand\x00fabric:networking"

    assert decode_channels(payload) == ["minecraft:brand", "fabric:networking"]


def test_decode_channels_returns_single_channel():
    assert decode_channels(b"minecraft:brand") == ["minecraft:brand"]


def test_decode_channels_returns_empty_list_for_empty_payload():
    assert decode_channels(b"") == []


def test_decode_channels_keeps_multi_byte_channel_names():
    assert decode_channels("ex:ü\x00ex:b".encode()) == ["ex:ü", "ex:b"]


@pytest.mark.parametrize(
    "payload",
    [b"a\x00\x00b", b"\x00a", b"a\x00"],
    ids=["empty_in_middle", "empty_first", "empty_last"],
)
def test_decode_channels_rejects_empty_channel_name(payload):
    with pytest.raises(ValueError, match="empty channel"):
        decode_channels(payload)


def test_decode_channels_rejects_invalid_utf8():
    with pytest.raises(ValueError, match="UTF-8"):
        decode_channels(b"ok\x00\xff")


def test_decode_module_does_not_import_the_lake_package():
    tree = ast.parse(DECODE_SOURCE.read_text(encoding="utf-8"))
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            imported.update(alias.name for alias in node.names)
        elif isinstance(node, ast.ImportFrom) and node.module:
            imported.add(node.module)

    assert not {name for name in imported if name.split(".")[0] == "lake"}
